// Publishes the IIFE build as _ds_bundle.js, the file the specimen cards load.
//
// Kept as a copy step rather than pointing tsup's outDir at the repo root, where
// a `clean` would have the whole repository in range.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { root, sourceHash, HASH_MARKER } from './bundle-sources.mjs';

const built = join(root, 'dist', 'ds-bundle.global.js');
const target = join(root, '_ds_bundle.js');

if (!existsSync(built)) {
  console.error(`Expected ${built} — run tsup first.`);
  process.exit(1);
}

const header = `// GENERATED by \`npm run build\` from index.ts — do not edit.
//
// The browser bundle for the specimen cards in components/ and guidelines/, and
// for the two UI kits. Exposes the library on
// window.LingoToolboxDesignSystem_898611 and expects React to already be on the
// page; it deliberately carries no React of its own.
//
// It contains the components only. The UI-kit screens load their own .jsx
// alongside this file and assign themselves to window.
//
// ${HASH_MARKER} ${sourceHash()}
// Checked by scripts/check-bundle-fresh.mjs — Pages serves this file straight
// from git, so a stale copy would publish specimens of components that no
// longer ship.
`;

const code = readFileSync(built, 'utf8');
writeFileSync(target, `${header}${code}`);

const kb = (s) => `${Math.round(s / 1024)} KB`;
console.log(`_ds_bundle.js written — ${kb(Buffer.byteLength(header) + Buffer.byteLength(code))}`);
